mapper.select:
SELECT history.* FROM () history
WHERE history.approved_at >= #{fromUtc} AND history.approved_at < #{toUtc}
  AND history.user_card_id = #{userCardId}
  AND history.benefit_type = #{benefitType}
ORDER BY GREATEST(history.benefit_amount, history.missed_benefit_amount) DESC, history.approved_at DESC, history.benefit_history_id DESCORDER BY history.approved_at DESC, history.benefit_history_id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM () history
WHERE history.approved_at >= #{fromUtc} AND history.approved_at < #{toUtc}
  AND history.user_card_id = #{userCardId}
  AND history.benefit_type = #{benefitType}
